/**
 * Instruction-tier plugins (Grok Build, Muse Code, Zed): rules + skills, no hooks.
 * Their content is generated by `pnpm plugins:sync` (checked by plugins:check);
 * this checks the wiring each agent reads.
 */
import { describe, it, expect } from "vitest";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const repo = join(here, "..", "..");
const plugin = (name: string) => join(repo, "plugins", name);
const SKILLS = ["contextnest-capture", "contextnest-curate", "contextnest-recall", "contextnest-structure"];

describe.each(["grok", "muse", "zed"])("%s plugin", (name) => {
  it("ships the four portable skills and the rules, and no hooks", () => {
    expect(readdirSync(join(plugin(name), "skills")).sort()).toEqual(SKILLS);
    const rules = readFileSync(join(plugin(name), "AGENTS.md"), "utf-8");
    expect(rules).toContain("ContextNest Operating Rules");
    expect(rules).toContain("`/contextnest:setup` command → no setup skill here");
    // Grok ignores the output of every hook but PreToolUse; Muse's payload is undocumented; Zed has no hooks.
    expect(existsSync(join(plugin(name), "hooks"))).toBe(false);
    expect(existsSync(join(plugin(name), "core"))).toBe(false);
  });
});

describe("grok marketplace", () => {
  it("the repo-root marketplace points at the Grok plugin, whose manifest names it", () => {
    const market = JSON.parse(readFileSync(join(repo, ".grok-plugin", "marketplace.json"), "utf-8"));
    const entry = market.plugins.find((p: any) => p.name === "contextnest");
    expect(entry.source).toBe("./plugins/grok");
    const manifest = JSON.parse(readFileSync(join(repo, entry.source, "plugin.json"), "utf-8"));
    expect(manifest.name).toBe("contextnest");
  });
});
